  insert into public.map_quest_segments (quest_id, sort, name) values (85, 10, null) returning id into seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (85, seg, 10, 'note', 'Bring a pick and a rope.', null, null, null, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Required equipment: Pick, Rope');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (85, seg, 20, 'go', 'Enter the Edron Hero Cave.', 33164, 31638, 7, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'First you have to enter the Edron Hero Cave (Mapper Coords 129.140, 123.150, 7).');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (85, seg, 30, 'go', 'Go down through the Hero Cave (open the hole on the way with your pick) and head west to the lone gravestone: the teleporter next to it leads to the Parchment Room. Get ready for a demon before you step in.', 33234, 31642, 13, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Use a pick to open the hole. Now go down and head to the west. Here you will find a single gravestone and a teleporter to a big room with one Demon inside, the Parchment Room.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (85, seg, 40, 'kill', 'Kill the demon in the Parchment Room.', 33230, 31643, 14, null, 'Demon', '[]'::jsonb, null, '[]'::jsonb, false, 'Get prepared to face the demon and enter the teleporter. After you have killed the Demon, go to the coffin in the middle of the room.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (85, seg, 50, 'reward', 'The coffin in the middle of the room: pushing the yellow parchment on it makes 4 demons appear around you. Kill them, or open the coffin, grab the reward (a key) and run.', 33230, 31643, 14, null, null, '[]'::jsonb, 1983, '[]'::jsonb, false, 'When you push the Yellow Parchment (Buried Forever) 4 Demons will spawn around you. Now you can decide to kill the demons or to grab the reward and run away. You have to open the coffin to get the reward.');
  insert into public.map_quest_segments (quest_id, sort, name) values (87, 10, null) returning id into seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (87, seg, 10, 'note', 'A team of four players, each level 100 or higher (130 recommended), none of whom has done this quest. Bring plenty of healing.', null, null, null, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'This quest needs a team of four players. It mandates a full team of four individuals who have not previously completed this quest. It is recommended that you be over Level 130 to succeed.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (87, seg, 20, 'go', 'Enter the Edron Hero Cave (hunters outside).', 33164, 31638, 7, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'The quest is located in the central cave of north Edron, the Hero Cave. First encounter is Hunters outside the cave.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (87, seg, 30, 'go', 'Down through the Hero Cave to the deepest floor (wild warriors, demon skeletons, priestesses, dragons, monks, heroes, minotaur guards). Take the passage south across from the fire elemental room to the level 100 gate of expertise.', 33213, 31671, 13, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Three levels down of Wild Warriors, Demon Skeletons and Priestesses. The fourth level has 3 Dragons. Fifth has 2 Monks and a Hero. Go on to the next passages that goes south, across from the Fire Elemental room. Hunters and such are here, and at the end is an level 100 gate of expertise and a quest door that leads to the teleport room.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (87, seg, 40, 'go', 'Through the gate and the quest door: all four stand on the four stone tiles in a row, the blocker (highest level) on the east one, next to the lever. The east player pulls the lever.', 33225, 31671, 13, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'The four members of the team must each stand on the four tiles. Once all four members are in place, the lever must be pushed in order to teleport the entire team instantaneously to the dungeon. Remember, the blocker or highest level should be farthest to the right.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (87, seg, 50, 'kill', 'The lever sends you to a room with six demons: two north, two south, two in front of the door east. Kill only the two in front of the door, both at once on the first.', 33224, 31659, 13, null, 'Demon', '[]'::jsonb, null, '[]'::jsonb, false, 'Upon entering you will see 6 Angry Demons. Attack only the two staying between the team and the door that leads to the reward room to the east. Make sure the entire team attacks the first of the two demons at the same time in order to kill it as fast as possible.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (87, seg, 60, 'go', 'Run east through the door to the reward room and close it behind you.', 33225, 31659, 13, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Once the two demons are dead, immediately run east through the door which will not be locked. Close the door behind you so that stray Fire Elementals and great fireball attacks do not make it through the door.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (87, seg, 70, 'reward', 'Choose ONE reward, you can only take one: the demon armor.', 33227, 31656, 13, null, null, '[[3388,1]]'::jsonb, 2472, '[]'::jsonb, false, 'You can only enter this door once, so choose your reward wisely. Demon Armor');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (87, seg, 80, 'reward', 'Or the magic sword.', 33229, 31656, 13, null, null, '[[3288,1]]'::jsonb, 2472, '[]'::jsonb, false, 'Magic Sword (Atk:48 Def:35 +3) It''s the Sword of Valor.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (87, seg, 90, 'reward', 'Or the stonecutter axe.', 33231, 31656, 13, null, null, '[[3319,1]]'::jsonb, 2472, '[]'::jsonb, false, 'Stonecutter''s Axe (Atk:50 Def:30 +3) You feel the power of this Mighty Axe.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (87, seg, 100, 'reward', 'Or the present.', 33233, 31656, 13, null, null, '[[2856,1]]'::jsonb, 2472, '[]'::jsonb, false, 'Annihilation Bear: I braved the Annihilator and all I got is this lousy teddy bear.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (87, seg, 110, 'go', 'The teleporter east of the chests takes you back in front of the level 100 gate.', 33236, 31659, 13, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'After choosing your reward, go through the teleport that is east of the reward choices. This will teleport you in front of the level 100 door at the beginning of the quest.');
  insert into public.map_quest_segments (quest_id, sort, name) values (89, 10, 'Access to the Isle of the Kings') returning id into seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (89, seg, 10, 'note', 'Bring a rope and a shovel.', null, null, null, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Required Equipment: Rope, Shovel');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (89, seg, 20, 'go', 'West of Carlin: go under the wall into the Ghostlands through the hole.', 32218, 31767, 7, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'First, enter the Ghostlands west of Carlin by going under the wall through the hole (Mapper Coords 125.219, 124.24, 7).');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (89, seg, 30, 'go', 'In the Ghostlands, go down inside the abandoned house to the south.', 32246, 31837, 7, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Once, in the Ghostlands, go to the abandoned house to the south (Mapper Coords 125.246, 124.93, 7), and go down inside it.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (89, seg, 40, 'go', 'In the basement (a demon skeleton, a ghoul or two) follow the corridor south and go down the stairs.', 32242, 31850, 8, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Once in the house basement you may face a Demon Skeleton and a Ghoul or two. From here, follow the corridor to the south, and go down the stairs.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (89, seg, 50, 'go', 'Go east to the end of the passage (stalkers; north are more stalkers, demon skeletons and a wild warrior), around to the south room (demon skeletons, stalkers, ghouls) and up the stairs.', 32251, 31867, 8, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'On this level, go east to the end of the passage. Then go around to the south room. In this final room are about 2 Demon Skeletons, 2 Stalkers, and 2-4 Ghouls, here go up the stairs.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (89, seg, 60, 'reward', 'Use the head of the top coffin: the family brooch.', 32248, 31866, 8, null, null, '[[3205,1]]'::jsonb, 2476, '[]'::jsonb, false, 'Simply "use" the head of the top coffin to find the Family Brooch.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (89, seg, 70, 'talk', 'Bring the brooch to Dalbrect and give it to him: from now on he sails you to the Isle of the Kings.', null, null, null, 'Dalbrect', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Sorry my friend, the monks don''t allow me to talk to you because of your intrusion in their chambers. Unless you plea to the abbot for absolution I can do nothing for you.","fx":["ends the conversation"],"cond":["quest 220 above 0","quest 62 is 2"],"alts":[{"cond":["quest 220 above 0"],"reply":"The monks forbid me to talk to you for you evil deeds.","fx":["ends the conversation"]},{"reply":"Be greeted, traveler."}]},{"say":"brooch","reply":"You have recovered my brooch! I shall forever be in your debt, my friend!","cond":["quest 62 is 2"],"alts":[{"reply":"What? You want me to examine a brooch?"}]}]'::jsonb, false, 'After this, bring the brooch to Dalbrect and you will be able to go to the Isle of the Kings.');
  insert into public.map_quest_segments (quest_id, sort, name) values (89, 20, 'The investigation') returning id into seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (89, seg, 10, 'talk', 'Sail with Dalbrect to the Isle of the Kings (10 gold).', null, null, null, 'Dalbrect', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Sorry my friend, the monks don''t allow me to talk to you because of your intrusion in their chambers. Unless you plea to the abbot for absolution I can do nothing for you.","fx":["ends the conversation"],"cond":["quest 220 above 0","quest 62 is 2"],"alts":[{"cond":["quest 220 above 0"],"reply":"The monks forbid me to talk to you for you evil deeds.","fx":["ends the conversation"]},{"reply":"Be greeted, traveler."}]},{"say":"passage","reply":"I have only sailed to the isle of the kings once or twice. I dare not anger the monks by bringing travellers there without their permission."}]'::jsonb, false, 'Now you can ask him whenever you want for a passage and he will take you to the Isle of the Kings for 10gp.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (89, seg, 20, 'talk', 'Ask the abbot Costello about Brother Fugio and agree to investigate: you may now open the warded doors to the catacombs.', null, null, null, 'Costello', null, '[]'::jsonb, null, '[{"say":"hi","reply":"WHAT? You have to be that trespasser my brothers told me about! Entering the restricted area is a horrible crime!","cond":["quest 220 above 0"],"alts":[{"reply":"Welcome, <your name>! Feel free to tell me what has brought you here."}]},{"say":"fugio","reply":"To be honest, I fear the omen in my dreams may be true. Perhaps Fugio is unable to see the danger down there. Perhaps ... you are willing to investigate this matter?","cond":["quest 63 below 1"]},{"say":"yes","reply":"Thank you very much! From now on you may open the warded doors to the catacombs","fx":["quest 63 becomes 1","quest 64 becomes 1"],"alts":[{"other":true,"reply":"Please forgive an old man, I shouldn''t have asked a stranger anyways."}]}]'::jsonb, false, 'You first need to go to the Isle of the Kings and talk to the abbot there, Costello. Ask him about "Brother Fugio", and he will let you enter the catacombs and instruct you to search for a lost brother.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (89, seg, 30, 'go', 'Back in the Ghostlands near Carlin, go down into this cave (scorpions).', 32223, 31860, 7, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Get the Monk''s Diary from this cave (Mapper Coords 125.223, 124.117, 7) in the Ghostlands near Carlin. Head down to the cave, labelled A, which has several Scorpions.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (89, seg, 40, 'go', 'At the end of the cave, in a structure with undead (demon skeletons, stalkers, a bonelord): pull the switch, then hurry back to where the pair of magic walls were.', 32212, 31888, 12, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Go to the end of the cave and in a structure you will encounter some Undead Creatures like: Demon Skeletons, Stalkers, and a Bonelord. Defeat some of them, pull the switch and then haste back where the pair of magic walls were.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (89, seg, 50, 'note', 'Three levels down, in the large cave, the far right passage: kill the giant spider and pull the switch it guards, then hurry back to the magic walls.', null, null, null, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Go down three levels to the large cave in the last picture. The far right passage, labelled B, leads to a Giant Spider guarding a switch to lower one of the magic wall. Defeat the giant spider, pull the switch, and then Haste back to where the magic walls were.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (89, seg, 60, 'go', 'The whole team at once through where the magic walls were, and stay together: a spot before the hole puts the walls back. Go down the hole and follow the passage north (demon skeletons, ghosts, stalkers, ghouls, a mummy).', 32259, 31891, 10, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Get your whole team at once through where the magic walls were, at C, but stay together, because there is a spot before the hole that resets the walls. Go down the hole and follow the passage north. You will encounter Demon Skeletons, Ghosts, Stalkers, Ghouls, and a Mummy.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (89, seg, 70, 'reward', 'Use the dead human: a backpack with the monk''s diary (the book "They Are Coming") and some other things.', 32262, 31861, 11, null, null, '[[2854,1]]'::jsonb, 4240, '[]'::jsonb, false, 'Farther, you will find a Dead Human (Quest). "Use" the body and receive a Backpack with a book and some other things in it. This book is the Monk''s Diary.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (89, seg, 80, 'note', 'Go back down the passage and take the portal out of the cave.', null, null, null, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Go back down the passage and take the portal out of the cave.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (89, seg, 90, 'talk', 'On the Isle of the Kings, give the diary to Costello (the building on the east side): a blessed ankh. Say "diary" to him once more to finish the quest.', null, null, null, 'Costello', null, '[]'::jsonb, null, '[{"say":"hi","reply":"WHAT? You have to be that trespasser my brothers told me about! Entering the restricted area is a horrible crime!","cond":["quest 220 above 0"],"alts":[{"reply":"Welcome, <your name>! Feel free to tell me what has brought you here."}]},{"say":"diary","reply":"Do you want me to inspect a diary?","cond":["quest 219 is 0"],"alts":[{"cond":["quest 219 above 0"],"reply":"Thank you again for handing me that diary."}]},{"say":"yes","reply":"By the gods! This is brother Fugio''s handwriting and what I read is horrible indeed! You have done our order a great favour by giving this diary to me! Take this blessed Ankh. May it protect you in even your darkest hours.","fx":["takes monks diary","you get blessed ankh","quest 219 becomes 2"],"cond":["if you have monks diary"],"alts":[{"other":true,"reply":"Uhm, as you wish."}]}]'::jsonb, false, 'Take the book to the Isle of the Kings and talk to Costello, who is inside the building on the east side. Ask him about the diary. He will examine it and give you a Blessed Ankh.');
  insert into public.map_quest_segments (quest_id, sort, name) values (88, 10, 'Assistant Postman') returning id into seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 10, 'note', 'Bring food and about 700 gold for travel (and a crowbar, or buy one on the way).', null, null, null, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Since there is so much walking on "safe" paths, you should bring plenty of Food. Approximately 700 gp. Crowbar');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 20, 'talk', 'Mission 1: at the post office between Thais and Kazordoon, ask Kevin for a mission and join his guild. He sends you to check the postal routes.', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"mission","reply":"You are not a member of our guild yet! We have high standards for our members. To rise in our guild is a difficult but rewarding task. Are you interested in joining?","cond":["quest 227 below 1"],"alts":[{"cond":["quest 248 is 1","quest 250 < quest 249"],"reply":"Your eagerness is a virtue, young one, but first lets talk about advancement."},{"cond":["quest 248 is 1"],"reply":"You have mastered all our current missions. There''s nothing left to be done ... for now."},{"cond":["quest 245 is 1"],"reply":"You are not done with your current mission. Deliver that letter to king Markwin. Please report back when you are ready."},{"cond":["quest 245 is 2"],"reply":"You have delivered that letter? You are a true postofficer. All over the land bards shall praise your name. There are no missions for you left right now.","fx":["quest 248 becomes 1","quest 249 becomes 5"]},{"cond":["quest 244 is 1"],"reply":"You are not done with your current mission. Deliver those letters to Santa. Please report back when you are ready."},{"cond":["quest 244 is 2"],"reply":"You did it? I hope you did not catch a flu in the cold! However theres another mission for you. Are you interested?"},{"cond":["quest 246 is 1","quest 244 is 0"],"reply":"So are you ready for another Mission?"},{"cond":["quest 243 is 0","quest 242 is 1"],"reply":"You are not done with your current mission. Search for the whereabout of Postofficer Waldo. Please report back when you are ready."},{"cond":["quest 243 is 1"],"reply":"So Waldo is dead? This is grave news indeed. Did you recover his posthorn?"},{"cond":["quest 234 above 0","quest 234 below 7"],"reply":"You are not done with your current mission. We still need the measurements of several postofficers. Please report back when you are ready."},{"cond":["quest 234 is 7"],"reply":"Once more you have impressed me! Are you willing to do another job?"},{"cond":["quest 233 above 0","quest 233 below 10"],"reply":"You are not done with your current mission. Make sure Hugo chief is tailoring our new uniforms. Please report back when you are ready."},{"cond":["quest 233 is 10"],"reply":"Excellent! Another job well done! Would you accept another mission?","fx":["quest 249 becomes 3"]},{"cond":["quest 231 is 1"],"reply":"You are not done with your current mission. Deliver that present to Fibula. Please report back when you are ready."},{"cond":["quest 231 is 2"],"reply":"Splendid, I knew we could trust you. I would like to ask for your help in another matter. Are you interested?"},{"cond":["quest 230 is 1"],"reply":"Do you bring ONE bone for our officers'' safety fund or ALL bones at once?"},{"cond":["quest 230 above 1","quest 230 below 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 1","quest 230 is 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 20"],"reply":"You have made it! We have enough bones for the fund! You remind me of myself when I was young! Interested in another mission?"},{"cond":["quest 229 above 0","quest 229 below 3"],"reply":"You are not done with your current mission. Find David Brassacres and hand him that bill. Report when you are ready."},{"cond":["quest 229 is 3"],"reply":"You truly got him? Quite impressive. You are a very prommising candidate! I think I have another mission for you. Are you interested?"},{"cond":["quest 228 is 1"],"reply":"You are not done with your current mission. The mailbox is still not fixed. Report if you are ready."},{"cond":["quest 228 is 2"],"reply":"Excellent, you got it fixed! This will teach this mailbox a lesson indeed! Are you interested in another assignment?"},{"cond":["quest 227 below 5"],"reply":"You are not done with your current mission. Make sure all the passages are secure. Report if you are ready."},{"cond":["quest 227 is 5"],"reply":"So you have finally made it! I did not think that you would have it in you ... However: are you ready for another assignment?"}]},{"say":"yes","reply":"Hm, I might consider your proposal, but first you will have to prove your worth by doing some tasks for us. Are you willing to do that?","alts":[{"other":true,"reply":"I thought so. The mail service is not for just anyone."}]}]'::jsonb, false, 'Start out by talking to Kevin at his post office between Thais and Kazordoon. Ask him for a mission and tell him you are interested in joining his guild.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 30, 'note', 'Check the postal routes by travelling them: boat Thais to Carlin (110 gp), walk to the Femor Hills and take the carpet to Edron (60 gp), boat to Venore (40 gp), walk to Kazordoon and take the steam boat in the deepest cave to Cormaya (160 gp). Then back to Kevin (cheapest: through the rotworm caves to Edron, boat to Venore, walk).', null, null, null, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Head to Thais and take the Boat to Carlin (110 gp). Walk to Femor Hills and carpet to Edron (60 gp). Boat to Venore (40 gp). Walk to Kazordoon and in deepest cave, ride the Steam Boat to Cormaya (160 gp). Return to Kevin''s Post office.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 40, 'talk', 'Tell Kevin you completed the mission. Mission 2: fix the mailbox on Folda.', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"mission","reply":"You are not a member of our guild yet! We have high standards for our members. To rise in our guild is a difficult but rewarding task. Are you interested in joining?","cond":["quest 227 below 1"],"alts":[{"cond":["quest 248 is 1","quest 250 < quest 249"],"reply":"Your eagerness is a virtue, young one, but first lets talk about advancement."},{"cond":["quest 248 is 1"],"reply":"You have mastered all our current missions. There''s nothing left to be done ... for now."},{"cond":["quest 245 is 1"],"reply":"You are not done with your current mission. Deliver that letter to king Markwin. Please report back when you are ready."},{"cond":["quest 245 is 2"],"reply":"You have delivered that letter? You are a true postofficer. All over the land bards shall praise your name. There are no missions for you left right now.","fx":["quest 248 becomes 1","quest 249 becomes 5"]},{"cond":["quest 244 is 1"],"reply":"You are not done with your current mission. Deliver those letters to Santa. Please report back when you are ready."},{"cond":["quest 244 is 2"],"reply":"You did it? I hope you did not catch a flu in the cold! However theres another mission for you. Are you interested?"},{"cond":["quest 246 is 1","quest 244 is 0"],"reply":"So are you ready for another Mission?"},{"cond":["quest 243 is 0","quest 242 is 1"],"reply":"You are not done with your current mission. Search for the whereabout of Postofficer Waldo. Please report back when you are ready."},{"cond":["quest 243 is 1"],"reply":"So Waldo is dead? This is grave news indeed. Did you recover his posthorn?"},{"cond":["quest 234 above 0","quest 234 below 7"],"reply":"You are not done with your current mission. We still need the measurements of several postofficers. Please report back when you are ready."},{"cond":["quest 234 is 7"],"reply":"Once more you have impressed me! Are you willing to do another job?"},{"cond":["quest 233 above 0","quest 233 below 10"],"reply":"You are not done with your current mission. Make sure Hugo chief is tailoring our new uniforms. Please report back when you are ready."},{"cond":["quest 233 is 10"],"reply":"Excellent! Another job well done! Would you accept another mission?","fx":["quest 249 becomes 3"]},{"cond":["quest 231 is 1"],"reply":"You are not done with your current mission. Deliver that present to Fibula. Please report back when you are ready."},{"cond":["quest 231 is 2"],"reply":"Splendid, I knew we could trust you. I would like to ask for your help in another matter. Are you interested?"},{"cond":["quest 230 is 1"],"reply":"Do you bring ONE bone for our officers'' safety fund or ALL bones at once?"},{"cond":["quest 230 above 1","quest 230 below 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 1","quest 230 is 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 20"],"reply":"You have made it! We have enough bones for the fund! You remind me of myself when I was young! Interested in another mission?"},{"cond":["quest 229 above 0","quest 229 below 3"],"reply":"You are not done with your current mission. Find David Brassacres and hand him that bill. Report when you are ready."},{"cond":["quest 229 is 3"],"reply":"You truly got him? Quite impressive. You are a very prommising candidate! I think I have another mission for you. Are you interested?"},{"cond":["quest 228 is 1"],"reply":"You are not done with your current mission. The mailbox is still not fixed. Report if you are ready."},{"cond":["quest 228 is 2"],"reply":"Excellent, you got it fixed! This will teach this mailbox a lesson indeed! Are you interested in another assignment?"},{"cond":["quest 227 below 5"],"reply":"You are not done with your current mission. Make sure all the passages are secure. Report if you are ready."},{"cond":["quest 227 is 5"],"reply":"So you have finally made it! I did not think that you would have it in you ... However: are you ready for another assignment?"}]},{"say":"yes","reply":"Hm, I might consider your proposal, but first you will have to prove your worth by doing some tasks for us. Are you willing to do that?","alts":[{"other":true,"reply":"I thought so. The mail service is not for just anyone."}]}]'::jsonb, false, 'Tell Kevin you completed the mission.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 50, 'get', 'Get a crowbar (sold in Edron, Darashia, Kazordoon, north of Thais by Lubo, and Venore).', null, null, null, null, null, '[[3304,1]]'::jsonb, null, '[]'::jsonb, false, 'Get a Crowbar (can be purchased from Edron, Darashia, Kazordoon, North of Thais (Lubo) and Venore)');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 60, 'go', 'Take the ferry north-west of Carlin to Folda (20 gp).', 32233, 31677, 7, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Take the ferry to Folda (20 gp) - North-West of Carlin (Mapper Coords 125.233, 123.189, 7)');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 70, 'go', 'Climb to the top of the mountain and use the crowbar on the mailbox.', 32013, 31562, 4, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Climb to the top of the mountain and ''use'' the crowbar on the mailbox');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 80, 'talk', 'Back to Kevin: ask about advancement. You are now an Assistant Postman (cheaper parcels and letters).', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"advancement","reply":"You are worthy indeed. Do you want to advance in our guild?","cond":["quest 250 < quest 249"],"alts":[{"cond":["quest 250 >= quest 249"],"reply":"Sorry, but you are not yet ready for advancement."}]},{"say":"yes","reply":"I grant you the title of postman. You are now a full member of our guild. Here have your own officers hat and wear it with pride.","fx":["quest 250 becomes 2","you get post officers hat"],"cond":["quest 249 is 2"],"alts":[{"cond":["quest 249 is 3"],"reply":"From now on it shall be known that you are a grand postman. You are now a privileged member until the end of days. Most captains around the world have an agreement with our guild to transport our privileged members, like you, for less gold.","fx":["quest 250 becomes 3"]},{"cond":["quest 249 is 4"],"reply":"From now on you are a grand postman for special operations. You are an honoured member of our guild and earned the privilege of your own post horn. Here, take it.","fx":["quest 250 becomes 4","you get post horn"]},{"cond":["quest 249 is 5"],"reply":"I grant you the title of archpostman. You are a legend in our guild. As privilege of your newly aquired status you are allowed to make use of certain mailboxes in dangerous areas. Just look out for them and you''ll see.","fx":["quest 250 becomes 5"]}]}]'::jsonb, false, 'Return to Kevin and ask about advancement. You are now an Assistant Postman! (cheaper parcels and letters)');
  insert into public.map_quest_segments (quest_id, sort, name) values (88, 20, 'Postman') returning id into seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 10, 'talk', 'Mission 3: Kevin gives you a bill for a magician hat and rabbits, for a famous magician.', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"mission","reply":"You are not a member of our guild yet! We have high standards for our members. To rise in our guild is a difficult but rewarding task. Are you interested in joining?","cond":["quest 227 below 1"],"alts":[{"cond":["quest 248 is 1","quest 250 < quest 249"],"reply":"Your eagerness is a virtue, young one, but first lets talk about advancement."},{"cond":["quest 248 is 1"],"reply":"You have mastered all our current missions. There''s nothing left to be done ... for now."},{"cond":["quest 245 is 1"],"reply":"You are not done with your current mission. Deliver that letter to king Markwin. Please report back when you are ready."},{"cond":["quest 245 is 2"],"reply":"You have delivered that letter? You are a true postofficer. All over the land bards shall praise your name. There are no missions for you left right now.","fx":["quest 248 becomes 1","quest 249 becomes 5"]},{"cond":["quest 244 is 1"],"reply":"You are not done with your current mission. Deliver those letters to Santa. Please report back when you are ready."},{"cond":["quest 244 is 2"],"reply":"You did it? I hope you did not catch a flu in the cold! However theres another mission for you. Are you interested?"},{"cond":["quest 246 is 1","quest 244 is 0"],"reply":"So are you ready for another Mission?"},{"cond":["quest 243 is 0","quest 242 is 1"],"reply":"You are not done with your current mission. Search for the whereabout of Postofficer Waldo. Please report back when you are ready."},{"cond":["quest 243 is 1"],"reply":"So Waldo is dead? This is grave news indeed. Did you recover his posthorn?"},{"cond":["quest 234 above 0","quest 234 below 7"],"reply":"You are not done with your current mission. We still need the measurements of several postofficers. Please report back when you are ready."},{"cond":["quest 234 is 7"],"reply":"Once more you have impressed me! Are you willing to do another job?"},{"cond":["quest 233 above 0","quest 233 below 10"],"reply":"You are not done with your current mission. Make sure Hugo chief is tailoring our new uniforms. Please report back when you are ready."},{"cond":["quest 233 is 10"],"reply":"Excellent! Another job well done! Would you accept another mission?","fx":["quest 249 becomes 3"]},{"cond":["quest 231 is 1"],"reply":"You are not done with your current mission. Deliver that present to Fibula. Please report back when you are ready."},{"cond":["quest 231 is 2"],"reply":"Splendid, I knew we could trust you. I would like to ask for your help in another matter. Are you interested?"},{"cond":["quest 230 is 1"],"reply":"Do you bring ONE bone for our officers'' safety fund or ALL bones at once?"},{"cond":["quest 230 above 1","quest 230 below 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 1","quest 230 is 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 20"],"reply":"You have made it! We have enough bones for the fund! You remind me of myself when I was young! Interested in another mission?"},{"cond":["quest 229 above 0","quest 229 below 3"],"reply":"You are not done with your current mission. Find David Brassacres and hand him that bill. Report when you are ready."},{"cond":["quest 229 is 3"],"reply":"You truly got him? Quite impressive. You are a very prommising candidate! I think I have another mission for you. Are you interested?"},{"cond":["quest 228 is 1"],"reply":"You are not done with your current mission. The mailbox is still not fixed. Report if you are ready."},{"cond":["quest 228 is 2"],"reply":"Excellent, you got it fixed! This will teach this mailbox a lesson indeed! Are you interested in another assignment?"},{"cond":["quest 227 below 5"],"reply":"You are not done with your current mission. Make sure all the passages are secure. Report if you are ready."},{"cond":["quest 227 is 5"],"reply":"So you have finally made it! I did not think that you would have it in you ... However: are you ready for another assignment?"}]},{"say":"yes","reply":"Hm, I might consider your proposal, but first you will have to prove your worth by doing some tasks for us. Are you willing to do that?","alts":[{"other":true,"reply":"I thought so. The mail service is not for just anyone."}]}]'::jsonb, false, 'Ask Kevin for a new mission and receive a Bill for one Magician Hat and a bunch of rabbits to be delivered to a famous magician.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 20, 'talk', 'In Venore, below the depot: ask A Strange Fellow about his hat (4 times) until he gives in and takes the bill.', null, null, null, 'A Strange Fellow', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Uh? What do you want?!"},{"say":"hat","reply":"What? My hat?? Theres... nothing special about it!","cond":["quest 229 is 1"],"alts":[{"reply":"Get lost!","fx":["ends the conversation"]}]},{"say":"hat","reply":"Stop bugging me about that hat, do you listen?"},{"say":"hat","reply":"Hey! Don''t touch that hat! Leave it alone!!! Don''t do this!!!!"},{"say":"hat","reply":"Noooooo! Argh, ok, ok, I guess I can''t deny it anymore, I am David Brassacres, the magnificent, so what do you want?","fx":["summons a rabbit","summons a rabbit","summons a rabbit","summons a rabbit","quest 229 becomes 2"]},{"say":"bill","reply":"A bill? Oh boy so you are delivering another bill to poor me?","cond":["quest 229 is 2"],"alts":[{"reply":"Thats not my concern, you are probably looking for someone else and now get lost!","fx":["ends the conversation"]}]},{"say":"yes","reply":"Ok, ok, I''ll take it. I guess I have no other choice anyways. And now leave me alone in my misery please.","fx":["takes bill","quest 229 becomes 3"],"cond":["if you have bill"],"alts":[{"cond":["if you don''t have bill"],"reply":"Ha Ha! You have none!! Naanaanaanaaanaaaa!","fx":["ends the conversation"]},{"other":true,"reply":"Hoooraaaay! Uhm... I mean, thats fine..."}]}]'::jsonb, false, 'Walk to Venore and seek out A Strange Fellow below the Depot. Talk to him and keep asking about his ''hat'' (4 times) until he gives in and takes his ''bill''.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 30, 'talk', 'Back to Kevin. Mission 4: the post officers'' fund is out of bones for aggressive dogs.', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"mission","reply":"You are not a member of our guild yet! We have high standards for our members. To rise in our guild is a difficult but rewarding task. Are you interested in joining?","cond":["quest 227 below 1"],"alts":[{"cond":["quest 248 is 1","quest 250 < quest 249"],"reply":"Your eagerness is a virtue, young one, but first lets talk about advancement."},{"cond":["quest 248 is 1"],"reply":"You have mastered all our current missions. There''s nothing left to be done ... for now."},{"cond":["quest 245 is 1"],"reply":"You are not done with your current mission. Deliver that letter to king Markwin. Please report back when you are ready."},{"cond":["quest 245 is 2"],"reply":"You have delivered that letter? You are a true postofficer. All over the land bards shall praise your name. There are no missions for you left right now.","fx":["quest 248 becomes 1","quest 249 becomes 5"]},{"cond":["quest 244 is 1"],"reply":"You are not done with your current mission. Deliver those letters to Santa. Please report back when you are ready."},{"cond":["quest 244 is 2"],"reply":"You did it? I hope you did not catch a flu in the cold! However theres another mission for you. Are you interested?"},{"cond":["quest 246 is 1","quest 244 is 0"],"reply":"So are you ready for another Mission?"},{"cond":["quest 243 is 0","quest 242 is 1"],"reply":"You are not done with your current mission. Search for the whereabout of Postofficer Waldo. Please report back when you are ready."},{"cond":["quest 243 is 1"],"reply":"So Waldo is dead? This is grave news indeed. Did you recover his posthorn?"},{"cond":["quest 234 above 0","quest 234 below 7"],"reply":"You are not done with your current mission. We still need the measurements of several postofficers. Please report back when you are ready."},{"cond":["quest 234 is 7"],"reply":"Once more you have impressed me! Are you willing to do another job?"},{"cond":["quest 233 above 0","quest 233 below 10"],"reply":"You are not done with your current mission. Make sure Hugo chief is tailoring our new uniforms. Please report back when you are ready."},{"cond":["quest 233 is 10"],"reply":"Excellent! Another job well done! Would you accept another mission?","fx":["quest 249 becomes 3"]},{"cond":["quest 231 is 1"],"reply":"You are not done with your current mission. Deliver that present to Fibula. Please report back when you are ready."},{"cond":["quest 231 is 2"],"reply":"Splendid, I knew we could trust you. I would like to ask for your help in another matter. Are you interested?"},{"cond":["quest 230 is 1"],"reply":"Do you bring ONE bone for our officers'' safety fund or ALL bones at once?"},{"cond":["quest 230 above 1","quest 230 below 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 1","quest 230 is 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 20"],"reply":"You have made it! We have enough bones for the fund! You remind me of myself when I was young! Interested in another mission?"},{"cond":["quest 229 above 0","quest 229 below 3"],"reply":"You are not done with your current mission. Find David Brassacres and hand him that bill. Report when you are ready."},{"cond":["quest 229 is 3"],"reply":"You truly got him? Quite impressive. You are a very prommising candidate! I think I have another mission for you. Are you interested?"},{"cond":["quest 228 is 1"],"reply":"You are not done with your current mission. The mailbox is still not fixed. Report if you are ready."},{"cond":["quest 228 is 2"],"reply":"Excellent, you got it fixed! This will teach this mailbox a lesson indeed! Are you interested in another assignment?"},{"cond":["quest 227 below 5"],"reply":"You are not done with your current mission. Make sure all the passages are secure. Report if you are ready."},{"cond":["quest 227 is 5"],"reply":"So you have finally made it! I did not think that you would have it in you ... However: are you ready for another assignment?"}]},{"say":"yes","reply":"Hm, I might consider your proposal, but first you will have to prove your worth by doing some tasks for us. Are you willing to do that?","alts":[{"other":true,"reply":"I thought so. The mail service is not for just anyone."}]}]'::jsonb, false, 'Return to Kevin. Kevin will tell you the classic post officer''s plight - aggressive dogs. He will also tell you that they are running low on bones.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 40, 'get', 'Get 20 bones (190 oz): skeletons on Mount Sternum drop them.', null, null, null, null, null, '[[3115,20]]'::jsonb, null, '[]'::jsonb, false, 'Get 20 bones (the easiest way is to go to Mount Sternum and kill skeletons). Bones weigh 9.50oz each, so 20 will weigh 190oz.');
