  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 10, 'talk', 'Mission 5: deliver a present to Dermot on Fibula.', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"mission","reply":"You are not a member of our guild yet! We have high standards for our members. To rise in our guild is a difficult but rewarding task. Are you interested in joining?","cond":["quest 227 below 1"],"alts":[{"cond":["quest 248 is 1","quest 250 < quest 249"],"reply":"Your eagerness is a virtue, young one, but first lets talk about advancement."},{"cond":["quest 248 is 1"],"reply":"You have mastered all our current missions. There''s nothing left to be done ... for now."},{"cond":["quest 245 is 1"],"reply":"You are not done with your current mission. Deliver that letter to king Markwin. Please report back when you are ready."},{"cond":["quest 245 is 2"],"reply":"You have delivered that letter? You are a true postofficer. All over the land bards shall praise your name. There are no missions for you left right now.","fx":["quest 248 becomes 1","quest 249 becomes 5"]},{"cond":["quest 244 is 1"],"reply":"You are not done with your current mission. Deliver those letters to Santa. Please report back when you are ready."},{"cond":["quest 244 is 2"],"reply":"You did it? I hope you did not catch a flu in the cold! However theres another mission for you. Are you interested?"},{"cond":["quest 246 is 1","quest 244 is 0"],"reply":"So are you ready for another Mission?"},{"cond":["quest 243 is 0","quest 242 is 1"],"reply":"You are not done with your current mission. Search for the whereabout of Postofficer Waldo. Please report back when you are ready."},{"cond":["quest 243 is 1"],"reply":"So Waldo is dead? This is grave news indeed. Did you recover his posthorn?"},{"cond":["quest 234 above 0","quest 234 below 7"],"reply":"You are not done with your current mission. We still need the measurements of several postofficers. Please report back when you are ready."},{"cond":["quest 234 is 7"],"reply":"Once more you have impressed me! Are you willing to do another job?"},{"cond":["quest 233 above 0","quest 233 below 10"],"reply":"You are not done with your current mission. Make sure Hugo chief is tailoring our new uniforms. Please report back when you are ready."},{"cond":["quest 233 is 10"],"reply":"Excellent! Another job well done! Would you accept another mission?","fx":["quest 249 becomes 3"]},{"cond":["quest 231 is 1"],"reply":"You are not done with your current mission. Deliver that present to Fibula. Please report back when you are ready."},{"cond":["quest 231 is 2"],"reply":"Splendid, I knew we could trust you. I would like to ask for your help in another matter. Are you interested?"},{"cond":["quest 230 is 1"],"reply":"Do you bring ONE bone for our officers'' safety fund or ALL bones at once?"},{"cond":["quest 230 above 1","quest 230 below 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 1","quest 230 is 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 20"],"reply":"You have made it! We have enough bones for the fund! You remind me of myself when I was young! Interested in another mission?"},{"cond":["quest 229 above 0","quest 229 below 3"],"reply":"You are not done with your current mission. Find David Brassacres and hand him that bill. Report when you are ready."},{"cond":["quest 229 is 3"],"reply":"You truly got him? Quite impressive. You are a very prommising candidate! I think I have another mission for you. Are you interested?"},{"cond":["quest 228 is 1"],"reply":"You are not done with your current mission. The mailbox is still not fixed. Report if you are ready."},{"cond":["quest 228 is 2"],"reply":"Excellent, you got it fixed! This will teach this mailbox a lesson indeed! Are you interested in another assignment?"},{"cond":["quest 227 below 5"],"reply":"You are not done with your current mission. Make sure all the passages are secure. Report if you are ready."},{"cond":["quest 227 is 5"],"reply":"So you have finally made it! I did not think that you would have it in you ... However: are you ready for another assignment?"}]},{"say":"yes","reply":"Hm, I might consider your proposal, but first you will have to prove your worth by doing some tasks for us. Are you willing to do that?","alts":[{"other":true,"reply":"I thought so. The mail service is not for just anyone."}]}]'::jsonb, false, 'Ask about another mission. Kevin will tell you to deliver a present to Dermot on Fibula.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 20, 'reward', 'Open the right blinking door and take the present from the chest. DON''T open the present: it disappears (a new one costs 16,000 gold from Black Bert).', 32569, 32024, 6, null, null, '[[3218,1]]'::jsonb, 2472, '[]'::jsonb, false, 'As directed, open the right blinking door and take the present from the chest. DO NOT OPEN THE PRESENT!! If you try to open it, you will get nothing and the present will disappear.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 30, 'talk', 'Travel to Fibula and give Dermot the present.', null, null, null, 'Dermot', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Hello, traveller <your name>. How can I help you?"},{"say":"present","reply":"You have a present for me?? Really?","cond":["quest 231 is 1"],"alts":[{"reply":"I don''t understand what you are talking about."}]},{"say":"yes","reply":"Thank you very much!","fx":["takes present","quest 231 becomes 2"],"cond":["if you have present"],"alts":[{"reply":"What? There is no present, at least none for me! Stop this foolish jokes!","fx":["ends the conversation"]},{"other":true,"reply":"Hmm, maybe next time."}]}]'::jsonb, false, 'Travel to Fibula to Dermot and give him the present.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 40, 'talk', 'Back to Kevin. Mission 6: new uniforms.', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"mission","reply":"You are not a member of our guild yet! We have high standards for our members. To rise in our guild is a difficult but rewarding task. Are you interested in joining?","cond":["quest 227 below 1"],"alts":[{"cond":["quest 248 is 1","quest 250 < quest 249"],"reply":"Your eagerness is a virtue, young one, but first lets talk about advancement."},{"cond":["quest 248 is 1"],"reply":"You have mastered all our current missions. There''s nothing left to be done ... for now."},{"cond":["quest 245 is 1"],"reply":"You are not done with your current mission. Deliver that letter to king Markwin. Please report back when you are ready."},{"cond":["quest 245 is 2"],"reply":"You have delivered that letter? You are a true postofficer. All over the land bards shall praise your name. There are no missions for you left right now.","fx":["quest 248 becomes 1","quest 249 becomes 5"]},{"cond":["quest 244 is 1"],"reply":"You are not done with your current mission. Deliver those letters to Santa. Please report back when you are ready."},{"cond":["quest 244 is 2"],"reply":"You did it? I hope you did not catch a flu in the cold! However theres another mission for you. Are you interested?"},{"cond":["quest 246 is 1","quest 244 is 0"],"reply":"So are you ready for another Mission?"},{"cond":["quest 243 is 0","quest 242 is 1"],"reply":"You are not done with your current mission. Search for the whereabout of Postofficer Waldo. Please report back when you are ready."},{"cond":["quest 243 is 1"],"reply":"So Waldo is dead? This is grave news indeed. Did you recover his posthorn?"},{"cond":["quest 234 above 0","quest 234 below 7"],"reply":"You are not done with your current mission. We still need the measurements of several postofficers. Please report back when you are ready."},{"cond":["quest 234 is 7"],"reply":"Once more you have impressed me! Are you willing to do another job?"},{"cond":["quest 233 above 0","quest 233 below 10"],"reply":"You are not done with your current mission. Make sure Hugo chief is tailoring our new uniforms. Please report back when you are ready."},{"cond":["quest 233 is 10"],"reply":"Excellent! Another job well done! Would you accept another mission?","fx":["quest 249 becomes 3"]},{"cond":["quest 231 is 1"],"reply":"You are not done with your current mission. Deliver that present to Fibula. Please report back when you are ready."},{"cond":["quest 231 is 2"],"reply":"Splendid, I knew we could trust you. I would like to ask for your help in another matter. Are you interested?"},{"cond":["quest 230 is 1"],"reply":"Do you bring ONE bone for our officers'' safety fund or ALL bones at once?"},{"cond":["quest 230 above 1","quest 230 below 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 1","quest 230 is 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 20"],"reply":"You have made it! We have enough bones for the fund! You remind me of myself when I was young! Interested in another mission?"},{"cond":["quest 229 above 0","quest 229 below 3"],"reply":"You are not done with your current mission. Find David Brassacres and hand him that bill. Report when you are ready."},{"cond":["quest 229 is 3"],"reply":"You truly got him? Quite impressive. You are a very prommising candidate! I think I have another mission for you. Are you interested?"},{"cond":["quest 228 is 1"],"reply":"You are not done with your current mission. The mailbox is still not fixed. Report if you are ready."},{"cond":["quest 228 is 2"],"reply":"Excellent, you got it fixed! This will teach this mailbox a lesson indeed! Are you interested in another assignment?"},{"cond":["quest 227 below 5"],"reply":"You are not done with your current mission. Make sure all the passages are secure. Report if you are ready."},{"cond":["quest 227 is 5"],"reply":"So you have finally made it! I did not think that you would have it in you ... However: are you ready for another assignment?"}]},{"say":"yes","reply":"Hm, I might consider your proposal, but first you will have to prove your worth by doing some tasks for us. Are you willing to do that?","alts":[{"other":true,"reply":"I thought so. The mail service is not for just anyone."}]}]'::jsonb, false, 'Return to Kevin.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 50, 'talk', 'In Venore, upstairs where clothes are sold, ask Hugo about the new uniforms and the dress pattern: he has no idea where Kevin got it from.', null, null, null, 'Hugo', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Be greeted, <your name>!"},{"say":"uniform","reply":"A new uniform for the post officers? I am sorry but my dog ate the last dress pattern we used. You need to supply us with a new dress pattern.","cond":["quest 233 is 1"],"alts":[{"reply":"I don''t get it, what uniforms you are talking about."}]},{"say":"dress pattern","reply":"It was ... wonderous beyond wildest imaginations! I have no clue where Kevin Postner got it from. Better ask him.","fx":["quest 233 becomes 2"],"cond":["quest 233 is 1"],"alts":[{"cond":["quest 233 above 1","quest 233 below 9"],"reply":"I already told you to ask your boss about that issue."},{"cond":["quest 233 is 9"],"reply":"By the gods of fashion! Didn''t it do that I fed the last dress pattern to my poor dog? Will this mocking of all which is taste and fashion never stop?? Ok, ok, you will get those ugly, stinking uniforms and now get lost, fashion terrorist.","fx":["quest 233 becomes 10","ends the conversation"]}]}]'::jsonb, false, 'Travel to Venore and talk to Hugo. He is located upstairs where dresses and other wears are being sold. Ask Hugo about new ''uniforms'' and new ''dress pattern''.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 60, 'talk', 'Tell Kevin about the dress patterns: he sends you to Talphion in Kazordoon.', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"dress pattern","reply":"Fine, fine. I think that should do it. Tell Hugo that we order those uniforms. The completed dress pattern will soon arrive in Venore. Report to me when you have talked to him.","fx":["quest 233 becomes 9"],"cond":["quest 233 is 8"],"alts":[{"reply":"The queen has sent me the samples we needed. The next part is tricky. We need the uniforms to emanate some odor that dogs hate.The dog with the best ''taste'' in that field is Noodles, the dog of King Tibianus. Do you understand so far?"},{"cond":["quest 233 is 2"],"reply":"Oh yes, where did we get that from ...? Let''s see, first ask the great technomancer in Kazordoon for the technical details. Return here afterwards.","fx":["quest 233 becomes 3"]},{"cond":["quest 233 is 4"],"reply":"The mail with Talphion''s instructions just arrived. I remember we asked Queen Eloise of Carlin for the perfect colours. Go there, ask her about the UNIFORMS and report back here.","fx":["quest 233 becomes 5"]}]}]'::jsonb, false, 'Return to Kevin to say ''dress patterns''. He will send you to Talphion in Kazordoon.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 70, 'talk', 'In Kazordoon, on the level with the rats, the west end of the passage west of the shops, down two staircases and north: say "dress pattern" to Talphion a few times until he understands. He sends a letter to Kevin.', null, null, null, 'Talphion', null, '[]'::jsonb, null, '[{"say":"hi","reply":"HIHOOOO <your name>! <waves his hands>"},{"say":"dress pattern","reply":"DRESS FLATTEN? WHO WANTS ME TO FLATTEN A DRESS?","cond":["quest 233 is 3"],"alts":[{"cond":["quest 233 not 3"],"reply":"DRESS FLATTEN? WHO WANTS ME TO FLATTEN A DRESS?"}]},{"say":"dress pattern","reply":"A PRESS LANTERN? NEVER HEARD ABOUT IT!"},{"say":"dress pattern","reply":"CHESS? I DONT PLAY CHESS!"}]'::jsonb, false, 'Go north to Kazordoon and talk to Talphion the technomancer. Say ''dress patterns'' a few times until he understands you. He will send a letter to Kevin.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 80, 'talk', 'Ask Kevin about the dress pattern: he sends you to Queen Eloise for the colours.', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"dress pattern","reply":"Fine, fine. I think that should do it. Tell Hugo that we order those uniforms. The completed dress pattern will soon arrive in Venore. Report to me when you have talked to him.","fx":["quest 233 becomes 9"],"cond":["quest 233 is 8"],"alts":[{"reply":"The queen has sent me the samples we needed. The next part is tricky. We need the uniforms to emanate some odor that dogs hate.The dog with the best ''taste'' in that field is Noodles, the dog of King Tibianus. Do you understand so far?"},{"cond":["quest 233 is 2"],"reply":"Oh yes, where did we get that from ...? Let''s see, first ask the great technomancer in Kazordoon for the technical details. Return here afterwards.","fx":["quest 233 becomes 3"]},{"cond":["quest 233 is 4"],"reply":"The mail with Talphion''s instructions just arrived. I remember we asked Queen Eloise of Carlin for the perfect colours. Go there, ask her about the UNIFORMS and report back here.","fx":["quest 233 becomes 5"]}]}]'::jsonb, false, 'Go Back to Kevin and ask about ''dress pattern''. He will acknowledge the message from Talphion, and send you to Queen Eloise for the perfect colors.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 90, 'talk', 'In Carlin, say "hail queen" to Queen Eloise and ask about the uniforms: she sends samples to Kevin.', null, null, null, 'Queen Eloise', null, '[]'::jsonb, null, '[{"say":"hail queen","reply":"I greet thee, my loyal subject."},{"say":"uniform","reply":"I remember about those uniforms, they had a camouflage inlay so they could be worn the inside out too. I will send some colorsamples via mail to Mr. Postner.","fx":["quest 233 becomes 6"],"cond":["quest 233 is 5"],"alts":[{"reply":"The uniforms of our guards and soldiers are of unparraleled quality of course."}]}]'::jsonb, false, 'Go north to Carlin and find Queen Eloise. Say ''Hail Queen'' and ask about ''uniforms.'' She will send some samples to Kevin.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 100, 'talk', 'Ask Kevin about the dress pattern (don''t say mission): find out which smell dogs hate most; Noodles, King Tibianus'' dog, has the best nose.', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"dress pattern","reply":"Fine, fine. I think that should do it. Tell Hugo that we order those uniforms. The completed dress pattern will soon arrive in Venore. Report to me when you have talked to him.","fx":["quest 233 becomes 9"],"cond":["quest 233 is 8"],"alts":[{"reply":"The queen has sent me the samples we needed. The next part is tricky. We need the uniforms to emanate some odor that dogs hate.The dog with the best ''taste'' in that field is Noodles, the dog of King Tibianus. Do you understand so far?"},{"cond":["quest 233 is 2"],"reply":"Oh yes, where did we get that from ...? Let''s see, first ask the great technomancer in Kazordoon for the technical details. Return here afterwards.","fx":["quest 233 becomes 3"]},{"cond":["quest 233 is 4"],"reply":"The mail with Talphion''s instructions just arrived. I remember we asked Queen Eloise of Carlin for the perfect colours. Go there, ask her about the UNIFORMS and report back here.","fx":["quest 233 becomes 5"]}]}]'::jsonb, false, 'Return to Kevin and ask about ''dress patterns''. DON''T SAY MISSION. He will tell you to figure out what smell dogs hate the most. He says that Noodles, King Tibianus''s dog has the best sense of smell.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 110, 'get', 'Gather a mouldy cheese, a banana skin and a dirty fur.', null, null, null, null, null, '[[3120,1],[3104,1],[3105,1]]'::jsonb, null, '[]'::jsonb, false, 'Gather the Mouldy Cheese, Banana Skin and a Dirty Fur');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 120, 'talk', 'In Thais castle, let Noodles sniff each one and ask "do you like that?", until he spits.', null, null, null, 'Noodles', null, '[]'::jsonb, null, '[{"say":"hi","reply":"<sniff> Woof! <sniff>"},{"say":"sniff banana","reply":"Woof!","fx":["ends the conversation"],"cond":["quest 233 not 7"],"alts":[{"cond":["quest 233 is 7","quest 251 is 1"],"reply":"<sniff> <sniff>"},{"cond":["quest 233 is 7","quest 251 is 2"],"reply":"<sniff> <sniff>"},{"cond":["quest 233 is 7","quest 251 is 3"],"reply":"<sniff> <sniff>"}]}]'::jsonb, false, 'Go to Thais Castle, and talk to Noodles, the king''s dog. Say "hi", "sniff banana skin", "do you like that?", "hi", "sniff dirty fur", "do you like that?", etc. Continue doing this until Noodles spits.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 130, 'talk', 'Tell Kevin about the dress pattern: he mails the patterns to Hugo; tell Hugo they''re ordering them.', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"dress pattern","reply":"Fine, fine. I think that should do it. Tell Hugo that we order those uniforms. The completed dress pattern will soon arrive in Venore. Report to me when you have talked to him.","fx":["quest 233 becomes 9"],"cond":["quest 233 is 8"],"alts":[{"reply":"The queen has sent me the samples we needed. The next part is tricky. We need the uniforms to emanate some odor that dogs hate.The dog with the best ''taste'' in that field is Noodles, the dog of King Tibianus. Do you understand so far?"},{"cond":["quest 233 is 2"],"reply":"Oh yes, where did we get that from ...? Let''s see, first ask the great technomancer in Kazordoon for the technical details. Return here afterwards.","fx":["quest 233 becomes 3"]},{"cond":["quest 233 is 4"],"reply":"The mail with Talphion''s instructions just arrived. I remember we asked Queen Eloise of Carlin for the perfect colours. Go there, ask her about the UNIFORMS and report back here.","fx":["quest 233 becomes 5"]}]}]'::jsonb, false, 'Return to Kevin and mention "dress pattern". He will tell you he is mailing the patterns to Hugo, and ask you to tell Hugo that they are ordering them.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 140, 'talk', 'Tell Hugo about the dress pattern: he insults it but agrees to make them.', null, null, null, 'Hugo', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Be greeted, <your name>!"},{"say":"dress pattern","reply":"It was ... wonderous beyond wildest imaginations! I have no clue where Kevin Postner got it from. Better ask him.","fx":["quest 233 becomes 2"],"cond":["quest 233 is 1"],"alts":[{"cond":["quest 233 above 1","quest 233 below 9"],"reply":"I already told you to ask your boss about that issue."},{"cond":["quest 233 is 9"],"reply":"By the gods of fashion! Didn''t it do that I fed the last dress pattern to my poor dog? Will this mocking of all which is taste and fashion never stop?? Ok, ok, you will get those ugly, stinking uniforms and now get lost, fashion terrorist.","fx":["quest 233 becomes 10","ends the conversation"]}]}]'::jsonb, false, 'Return again to Hugo, ''dress pattern.'' He will insult the patterns, but ultimately agree to making them.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 150, 'talk', 'Back to Kevin: ask about advancement. You are now a Grand Postman (cheaper boat trips).', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"advancement","reply":"You are worthy indeed. Do you want to advance in our guild?","cond":["quest 250 < quest 249"],"alts":[{"cond":["quest 250 >= quest 249"],"reply":"Sorry, but you are not yet ready for advancement."}]},{"say":"yes","reply":"I grant you the title of postman. You are now a full member of our guild. Here have your own officers hat and wear it with pride.","fx":["quest 250 becomes 2","you get post officers hat"],"cond":["quest 249 is 2"],"alts":[{"cond":["quest 249 is 3"],"reply":"From now on it shall be known that you are a grand postman. You are now a privileged member until the end of days. Most captains around the world have an agreement with our guild to transport our privileged members, like you, for less gold.","fx":["quest 250 becomes 3"]},{"cond":["quest 249 is 4"],"reply":"From now on you are a grand postman for special operations. You are an honoured member of our guild and earned the privilege of your own post horn. Here, take it.","fx":["quest 250 becomes 4","you get post horn"]},{"cond":["quest 249 is 5"],"reply":"I grant you the title of archpostman. You are a legend in our guild. As privilege of your newly aquired status you are allowed to make use of certain mailboxes in dangerous areas. Just look out for them and you''ll see.","fx":["quest 250 becomes 5"]}]}]'::jsonb, false, 'Return to Kevin. Ask about advancement. You are now a Grand Postman! (This grants you travel discounts on boats)');
  insert into public.map_quest_segments (quest_id, sort, name) values (88, 40, 'Grand Postman for Special Operations') returning id into seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 10, 'talk', 'Mission 7: Hugo needs the measurements of all post officers (any order). Bring about 200 gold, 12 arrows and grapes.', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"mission","reply":"You are not a member of our guild yet! We have high standards for our members. To rise in our guild is a difficult but rewarding task. Are you interested in joining?","cond":["quest 227 below 1"],"alts":[{"cond":["quest 248 is 1","quest 250 < quest 249"],"reply":"Your eagerness is a virtue, young one, but first lets talk about advancement."},{"cond":["quest 248 is 1"],"reply":"You have mastered all our current missions. There''s nothing left to be done ... for now."},{"cond":["quest 245 is 1"],"reply":"You are not done with your current mission. Deliver that letter to king Markwin. Please report back when you are ready."},{"cond":["quest 245 is 2"],"reply":"You have delivered that letter? You are a true postofficer. All over the land bards shall praise your name. There are no missions for you left right now.","fx":["quest 248 becomes 1","quest 249 becomes 5"]},{"cond":["quest 244 is 1"],"reply":"You are not done with your current mission. Deliver those letters to Santa. Please report back when you are ready."},{"cond":["quest 244 is 2"],"reply":"You did it? I hope you did not catch a flu in the cold! However theres another mission for you. Are you interested?"},{"cond":["quest 246 is 1","quest 244 is 0"],"reply":"So are you ready for another Mission?"},{"cond":["quest 243 is 0","quest 242 is 1"],"reply":"You are not done with your current mission. Search for the whereabout of Postofficer Waldo. Please report back when you are ready."},{"cond":["quest 243 is 1"],"reply":"So Waldo is dead? This is grave news indeed. Did you recover his posthorn?"},{"cond":["quest 234 above 0","quest 234 below 7"],"reply":"You are not done with your current mission. We still need the measurements of several postofficers. Please report back when you are ready."},{"cond":["quest 234 is 7"],"reply":"Once more you have impressed me! Are you willing to do another job?"},{"cond":["quest 233 above 0","quest 233 below 10"],"reply":"You are not done with your current mission. Make sure Hugo chief is tailoring our new uniforms. Please report back when you are ready."},{"cond":["quest 233 is 10"],"reply":"Excellent! Another job well done! Would you accept another mission?","fx":["quest 249 becomes 3"]},{"cond":["quest 231 is 1"],"reply":"You are not done with your current mission. Deliver that present to Fibula. Please report back when you are ready."},{"cond":["quest 231 is 2"],"reply":"Splendid, I knew we could trust you. I would like to ask for your help in another matter. Are you interested?"},{"cond":["quest 230 is 1"],"reply":"Do you bring ONE bone for our officers'' safety fund or ALL bones at once?"},{"cond":["quest 230 above 1","quest 230 below 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 1","quest 230 is 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 20"],"reply":"You have made it! We have enough bones for the fund! You remind me of myself when I was young! Interested in another mission?"},{"cond":["quest 229 above 0","quest 229 below 3"],"reply":"You are not done with your current mission. Find David Brassacres and hand him that bill. Report when you are ready."},{"cond":["quest 229 is 3"],"reply":"You truly got him? Quite impressive. You are a very prommising candidate! I think I have another mission for you. Are you interested?"},{"cond":["quest 228 is 1"],"reply":"You are not done with your current mission. The mailbox is still not fixed. Report if you are ready."},{"cond":["quest 228 is 2"],"reply":"Excellent, you got it fixed! This will teach this mailbox a lesson indeed! Are you interested in another assignment?"},{"cond":["quest 227 below 5"],"reply":"You are not done with your current mission. Make sure all the passages are secure. Report if you are ready."},{"cond":["quest 227 is 5"],"reply":"So you have finally made it! I did not think that you would have it in you ... However: are you ready for another assignment?"}]},{"say":"yes","reply":"Hm, I might consider your proposal, but first you will have to prove your worth by doing some tasks for us. Are you willing to do that?","alts":[{"other":true,"reply":"I thought so. The mail service is not for just anyone."}]}]'::jsonb, false, 'Kevin will tell you that Hugo needs the measurements of all of the Post Officers (in any order). Approximately 200 gp. 12 Arrows. Grapes');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 20, 'talk', 'Thais depot: Benjamin''s measurements.', null, null, null, 'Benjamin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Hello. How may I help you <your name>?"},{"say":"measurements","reply":"Oh they dont change that much since in the old days as... <tells a boring and confusing story about a cake, a parcel, himself and two squirrels, at least he tells you his measurements in the end>","fx":["quest 234 becomes quest 234+1","quest 236 becomes 1"],"cond":["quest 234 above 0","quest 236 below 1"]}]'::jsonb, false, 'Walk to Thais and get the measurements from Benjamin');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 30, 'talk', 'Carlin depot: Liane wants 12 arrows (Perac sells them) for her measurements.', null, null, null, 'Liane', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Hello <your name>. May I help you?"},{"say":"measurements","reply":"I have more urgent problem to attend then that. Those hawks are hunting my carrier pigeons. Bring me 12 arrows and I''ll see if I have the time for this nonsense. Do you have 12 arrows with you?","cond":["quest 234 above 0","quest 239 below 1"]},{"say":"yes","reply":"Great! Now I''ll teach them a lesson ... For those measurements ... <tells you her measurements>","fx":["takes 12 arrows","quest 234 becomes quest 234+1","quest 239 becomes 1"],"cond":["if you have 12 arrows"],"alts":[{"reply":"Fool, you have no 12 arrows."},{"other":true,"reply":"Don''t waste my time."}]}]'::jsonb, false, 'Take the ship to Carlin (100 gps), buy 12 arrows from Perac and get the measurements from Liane');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 40, 'talk', 'Ab''Dendriel, south-west of the depot: Olrik gambles for his measurements (5 gold per dice roll).', null, null, null, 'Olrik', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings, <your name>.","cond":["male characters only"],"alts":[{"cond":["female characters only"],"reply":"Greetings, <your name>. May I help you?"}]},{"say":"measurements","reply":"My measurements? Listen, lets make that a bit more exciting ... No, no, not what you think! I mean let''s gamble. I will roll a dice. If I roll a 6 you win and I''ll tell you what you need to know, else I win and get 5 gold. Deal?","cond":["quest 234 above 0","quest 240 below 1"]},{"say":"yes","reply":"Ok, here we go ... 6! You have won! How lucky you are! So listen ...<tells you what you need to know>","fx":["quest 234 becomes quest 234+1","quest 240 becomes 1"],"cond":["if you have 5 gp","random answer 6 (the NPC picks one)"],"alts":[{"other":true,"cond":["if you have 5 gp"],"reply":"Ok, and its ... <amount>! You have lost. He he. Another game?","fx":["takes 5 gp"]},{"other":true,"cond":["if you don''t have 5 gp"],"reply":"I am sorry, but you don''t have so much money."}]}]'::jsonb, false, 'Walk to Ab''Dendriel and get the measurements from Olrik (Good luck with the dice). Olrik gambles with you to give his measurements (5gp per roll, bring some gold)');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 50, 'talk', 'Kazordoon, north end of the depot: Lokur sends you to his armorer Kroox.', null, null, null, 'Lokur', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Hiho <your name>. May I help you?"},{"say":"measurements","reply":"Ask Kroox about that stuff.","cond":["quest 235 above 0"],"alts":[{"cond":["quest 234 above 0"],"reply":"Come on, I have no clue what they are. Better ask my armorer Kroox for such nonsense. Go and ask him for good ol'' Lokurs measurements, he''ll know.","fx":["quest 235 becomes 1"]}]}]'::jsonb, false, 'Walk to Kazordoon and talk to Lokur, who will send you to Kroox.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 60, 'talk', 'Kroox gives you Lokur''s measurements.', null, null, null, 'Kroox', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Welcome to Kroox Quality Armor, <your name>!"},{"say":"measurements","reply":"Hm, well I guess its ok to tell you ... <tells you about Lokurs measurements>","fx":["quest 234 becomes quest 234+1","quest 237 becomes 1"],"cond":["quest 235 above 0","quest 237 below 1"],"alts":[{"reply":"UH? No clue what you are talking about, jawoll."}]}]'::jsonb, false, 'Get the measurements from Kroox');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 70, 'talk', 'Edron, above the depot (wagon to the top of Kazordoon, carpet to Edron for 30 gold): Chrystal''s measurements.', null, null, null, 'Chrystal', null, '[]'::jsonb, null, '[{"say":"hi","reply":"At your service <your name>."},{"say":"measurements","reply":"If its necessary ... <tells you her measurements>","fx":["quest 234 becomes quest 234+1","quest 241 becomes 1"],"cond":["quest 234 above 0","quest 241 below 1"]}]'::jsonb, false, 'Use the wagon to go with Gewen on top of Kazordoon, take the carpet to Edron (30 gps) and get the measurements from Chrystal');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 80, 'talk', 'Venore, downstairs in the depot (boat from Edron, 30 gold): Dove wants one bunch of grapes (Rodney sells them for 3 gold).', null, null, null, 'Dove', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Be greeted, noble <your name>."},{"say":"measurements","reply":"Oh no! I knew that day would come! I am slightly above the allowed weight and if you can''t supply me with some grapes to slim down I will get fired. Do you happen to have some grapes with you?","cond":["quest 234 above 0","quest 238 below 1"]},{"say":"yes","reply":"Oh thank you! Thank you so much! So listen ... <whispers her measurements>","fx":["takes grapes","quest 234 becomes quest 234+1","quest 238 becomes 1"],"cond":["if you have grapes"],"alts":[{"reply":"Don''t tease me! You don''t have any."},{"other":true,"reply":"Oh, no! I might loose my job."}]}]'::jsonb, false, 'Take the ship to Venore (30 gps) and get the measurements from Dove. She will ask you for Grapes which you can buy from Rodney for 3gps.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 90, 'talk', 'Report back to Kevin. Mission 8: the courier Waldo is missing; find him, or at least his posthorn.', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"mission","reply":"You are not a member of our guild yet! We have high standards for our members. To rise in our guild is a difficult but rewarding task. Are you interested in joining?","cond":["quest 227 below 1"],"alts":[{"cond":["quest 248 is 1","quest 250 < quest 249"],"reply":"Your eagerness is a virtue, young one, but first lets talk about advancement."},{"cond":["quest 248 is 1"],"reply":"You have mastered all our current missions. There''s nothing left to be done ... for now."},{"cond":["quest 245 is 1"],"reply":"You are not done with your current mission. Deliver that letter to king Markwin. Please report back when you are ready."},{"cond":["quest 245 is 2"],"reply":"You have delivered that letter? You are a true postofficer. All over the land bards shall praise your name. There are no missions for you left right now.","fx":["quest 248 becomes 1","quest 249 becomes 5"]},{"cond":["quest 244 is 1"],"reply":"You are not done with your current mission. Deliver those letters to Santa. Please report back when you are ready."},{"cond":["quest 244 is 2"],"reply":"You did it? I hope you did not catch a flu in the cold! However theres another mission for you. Are you interested?"},{"cond":["quest 246 is 1","quest 244 is 0"],"reply":"So are you ready for another Mission?"},{"cond":["quest 243 is 0","quest 242 is 1"],"reply":"You are not done with your current mission. Search for the whereabout of Postofficer Waldo. Please report back when you are ready."},{"cond":["quest 243 is 1"],"reply":"So Waldo is dead? This is grave news indeed. Did you recover his posthorn?"},{"cond":["quest 234 above 0","quest 234 below 7"],"reply":"You are not done with your current mission. We still need the measurements of several postofficers. Please report back when you are ready."},{"cond":["quest 234 is 7"],"reply":"Once more you have impressed me! Are you willing to do another job?"},{"cond":["quest 233 above 0","quest 233 below 10"],"reply":"You are not done with your current mission. Make sure Hugo chief is tailoring our new uniforms. Please report back when you are ready."},{"cond":["quest 233 is 10"],"reply":"Excellent! Another job well done! Would you accept another mission?","fx":["quest 249 becomes 3"]},{"cond":["quest 231 is 1"],"reply":"You are not done with your current mission. Deliver that present to Fibula. Please report back when you are ready."},{"cond":["quest 231 is 2"],"reply":"Splendid, I knew we could trust you. I would like to ask for your help in another matter. Are you interested?"},{"cond":["quest 230 is 1"],"reply":"Do you bring ONE bone for our officers'' safety fund or ALL bones at once?"},{"cond":["quest 230 above 1","quest 230 below 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 1","quest 230 is 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 20"],"reply":"You have made it! We have enough bones for the fund! You remind me of myself when I was young! Interested in another mission?"},{"cond":["quest 229 above 0","quest 229 below 3"],"reply":"You are not done with your current mission. Find David Brassacres and hand him that bill. Report when you are ready."},{"cond":["quest 229 is 3"],"reply":"You truly got him? Quite impressive. You are a very prommising candidate! I think I have another mission for you. Are you interested?"},{"cond":["quest 228 is 1"],"reply":"You are not done with your current mission. The mailbox is still not fixed. Report if you are ready."},{"cond":["quest 228 is 2"],"reply":"Excellent, you got it fixed! This will teach this mailbox a lesson indeed! Are you interested in another assignment?"},{"cond":["quest 227 below 5"],"reply":"You are not done with your current mission. Make sure all the passages are secure. Report if you are ready."},{"cond":["quest 227 is 5"],"reply":"So you have finally made it! I did not think that you would have it in you ... However: are you ready for another assignment?"}]},{"say":"yes","reply":"Hm, I might consider your proposal, but first you will have to prove your worth by doing some tasks for us. Are you willing to do that?","alts":[{"other":true,"reply":"I thought so. The mail service is not for just anyone."}]}]'::jsonb, false, 'Report back to Kevin. Kevin tells you that the mail courier Waldo is missing, and that you need to find him, or at least his posthorn.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 100, 'go', 'Thais troll caves: open the hole with a shovel and go down.', 32489, 32260, 7, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'He is in the Thais Troll Caves (Mapper Coords 126.233, 126.4, 7). You will need a shovel to open the hole.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 110, 'reward', 'Go east and down the hole, north and east past the orcs and up the ladder. Waldo lies directly west, behind a sealed door (it only opens after Kevin told you about Waldo): use his body to get Waldo''s posthorn.', 32514, 32248, 8, null, null, '[]'::jsonb, 4240, '[]'::jsonb, false, 'Once in the caves, go east and down the hole. Then go north and east past the Orcs, and up the ladder. Waldo will be directly west, behind a sealed door. When you find his dead body, "use" it to get Waldos Posthorn.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 120, 'talk', 'With the posthorn, ask Kevin about advancement. You are now a Grand Postman for Special Operations (post horn). Free up 500 oz of capacity for the next mission.', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"advancement","reply":"You are worthy indeed. Do you want to advance in our guild?","cond":["quest 250 < quest 249"],"alts":[{"cond":["quest 250 >= quest 249"],"reply":"Sorry, but you are not yet ready for advancement."}]},{"say":"yes","reply":"I grant you the title of postman. You are now a full member of our guild. Here have your own officers hat and wear it with pride.","fx":["quest 250 becomes 2","you get post officers hat"],"cond":["quest 249 is 2"],"alts":[{"cond":["quest 249 is 3"],"reply":"From now on it shall be known that you are a grand postman. You are now a privileged member until the end of days. Most captains around the world have an agreement with our guild to transport our privileged members, like you, for less gold.","fx":["quest 250 becomes 3"]},{"cond":["quest 249 is 4"],"reply":"From now on you are a grand postman for special operations. You are an honoured member of our guild and earned the privilege of your own post horn. Here, take it.","fx":["quest 250 becomes 4","you get post horn"]},{"cond":["quest 249 is 5"],"reply":"I grant you the title of archpostman. You are a legend in our guild. As privilege of your newly aquired status you are allowed to make use of certain mailboxes in dangerous areas. Just look out for them and you''ll see.","fx":["quest 250 becomes 5"]}]}]'::jsonb, false, 'Go to Kevin with the Post Horn in your possession and ask for advancement. If you don''t have the required 500 capacity you need for the next mission, it is a good idea to buy a parcel from Wally and send whatever you do not need to yourself.');
  insert into public.map_quest_segments (quest_id, sort, name) values (88, 50, 'Arch Postman') returning id into seg;
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 10, 'talk', 'Mission 9: deliver letters to Santa Claus on Vega.', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"mission","reply":"You are not a member of our guild yet! We have high standards for our members. To rise in our guild is a difficult but rewarding task. Are you interested in joining?","cond":["quest 227 below 1"],"alts":[{"cond":["quest 248 is 1","quest 250 < quest 249"],"reply":"Your eagerness is a virtue, young one, but first lets talk about advancement."},{"cond":["quest 248 is 1"],"reply":"You have mastered all our current missions. There''s nothing left to be done ... for now."},{"cond":["quest 245 is 1"],"reply":"You are not done with your current mission. Deliver that letter to king Markwin. Please report back when you are ready."},{"cond":["quest 245 is 2"],"reply":"You have delivered that letter? You are a true postofficer. All over the land bards shall praise your name. There are no missions for you left right now.","fx":["quest 248 becomes 1","quest 249 becomes 5"]},{"cond":["quest 244 is 1"],"reply":"You are not done with your current mission. Deliver those letters to Santa. Please report back when you are ready."},{"cond":["quest 244 is 2"],"reply":"You did it? I hope you did not catch a flu in the cold! However theres another mission for you. Are you interested?"},{"cond":["quest 246 is 1","quest 244 is 0"],"reply":"So are you ready for another Mission?"},{"cond":["quest 243 is 0","quest 242 is 1"],"reply":"You are not done with your current mission. Search for the whereabout of Postofficer Waldo. Please report back when you are ready."},{"cond":["quest 243 is 1"],"reply":"So Waldo is dead? This is grave news indeed. Did you recover his posthorn?"},{"cond":["quest 234 above 0","quest 234 below 7"],"reply":"You are not done with your current mission. We still need the measurements of several postofficers. Please report back when you are ready."},{"cond":["quest 234 is 7"],"reply":"Once more you have impressed me! Are you willing to do another job?"},{"cond":["quest 233 above 0","quest 233 below 10"],"reply":"You are not done with your current mission. Make sure Hugo chief is tailoring our new uniforms. Please report back when you are ready."},{"cond":["quest 233 is 10"],"reply":"Excellent! Another job well done! Would you accept another mission?","fx":["quest 249 becomes 3"]},{"cond":["quest 231 is 1"],"reply":"You are not done with your current mission. Deliver that present to Fibula. Please report back when you are ready."},{"cond":["quest 231 is 2"],"reply":"Splendid, I knew we could trust you. I would like to ask for your help in another matter. Are you interested?"},{"cond":["quest 230 is 1"],"reply":"Do you bring ONE bone for our officers'' safety fund or ALL bones at once?"},{"cond":["quest 230 above 1","quest 230 below 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 1","quest 230 is 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 20"],"reply":"You have made it! We have enough bones for the fund! You remind me of myself when I was young! Interested in another mission?"},{"cond":["quest 229 above 0","quest 229 below 3"],"reply":"You are not done with your current mission. Find David Brassacres and hand him that bill. Report when you are ready."},{"cond":["quest 229 is 3"],"reply":"You truly got him? Quite impressive. You are a very prommising candidate! I think I have another mission for you. Are you interested?"},{"cond":["quest 228 is 1"],"reply":"You are not done with your current mission. The mailbox is still not fixed. Report if you are ready."},{"cond":["quest 228 is 2"],"reply":"Excellent, you got it fixed! This will teach this mailbox a lesson indeed! Are you interested in another assignment?"},{"cond":["quest 227 below 5"],"reply":"You are not done with your current mission. Make sure all the passages are secure. Report if you are ready."},{"cond":["quest 227 is 5"],"reply":"So you have finally made it! I did not think that you would have it in you ... However: are you ready for another assignment?"}]},{"say":"yes","reply":"Hm, I might consider your proposal, but first you will have to prove your worth by doing some tasks for us. Are you willing to do that?","alts":[{"other":true,"reply":"I thought so. The mail service is not for just anyone."}]}]'::jsonb, false, 'This time Kevin asks you to deliver some letters to Santa Claus on Vega.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 20, 'reward', 'Open the left sealed door and take the letterbag from the chest (500 oz: it won''t come out without the capacity, and nobody can carry it for you; a new one costs 8,000 gold from Black Bert).', 32567, 32024, 6, null, null, '[[3217,1]]'::jsonb, 2472, '[]'::jsonb, false, 'Open the left Sealed Door and get a Letterbag (it weighs 500 oz, and no one else can carry it for you, since it won''t come out of the chest unless you have the capacity). If you lost the letterbag you can buy a replacement from NPC Black Bert at the price of 8,000 gps.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 30, 'talk', 'Take Nielson''s raft to Vega.', null, null, null, 'Nielson', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Ahoi, young man <your name> and welcome to the Nordic Tibia Ferries.","cond":["male characters only"],"alts":[{"cond":["female characters only"],"reply":"Ahoi, young lady <your name> and welcome to the Nordic Tibia Ferries."}]}]'::jsonb, false, 'Take this letterbag to Vega by Nielson''s raft');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 40, 'go', 'West to Santa''s house: use the letterbag on Santa''s mailbox (it becomes a normal red bag).', 31948, 31711, 6, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'Go west to Santa''s house (Mapper Coords 124.211, 123.224, 7). Use the letterbag on Santa''s Mailbox. After you deliver the letters, it will become a normal Red Bag.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 50, 'talk', 'Back to Kevin for the last mission. Mission 10: a letter from his mother for Markwin in Mintwallin. A stealth ring helps: the first time you talk to Markwin he calls 8 minotaur bodyguards.', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"mission","reply":"You are not a member of our guild yet! We have high standards for our members. To rise in our guild is a difficult but rewarding task. Are you interested in joining?","cond":["quest 227 below 1"],"alts":[{"cond":["quest 248 is 1","quest 250 < quest 249"],"reply":"Your eagerness is a virtue, young one, but first lets talk about advancement."},{"cond":["quest 248 is 1"],"reply":"You have mastered all our current missions. There''s nothing left to be done ... for now."},{"cond":["quest 245 is 1"],"reply":"You are not done with your current mission. Deliver that letter to king Markwin. Please report back when you are ready."},{"cond":["quest 245 is 2"],"reply":"You have delivered that letter? You are a true postofficer. All over the land bards shall praise your name. There are no missions for you left right now.","fx":["quest 248 becomes 1","quest 249 becomes 5"]},{"cond":["quest 244 is 1"],"reply":"You are not done with your current mission. Deliver those letters to Santa. Please report back when you are ready."},{"cond":["quest 244 is 2"],"reply":"You did it? I hope you did not catch a flu in the cold! However theres another mission for you. Are you interested?"},{"cond":["quest 246 is 1","quest 244 is 0"],"reply":"So are you ready for another Mission?"},{"cond":["quest 243 is 0","quest 242 is 1"],"reply":"You are not done with your current mission. Search for the whereabout of Postofficer Waldo. Please report back when you are ready."},{"cond":["quest 243 is 1"],"reply":"So Waldo is dead? This is grave news indeed. Did you recover his posthorn?"},{"cond":["quest 234 above 0","quest 234 below 7"],"reply":"You are not done with your current mission. We still need the measurements of several postofficers. Please report back when you are ready."},{"cond":["quest 234 is 7"],"reply":"Once more you have impressed me! Are you willing to do another job?"},{"cond":["quest 233 above 0","quest 233 below 10"],"reply":"You are not done with your current mission. Make sure Hugo chief is tailoring our new uniforms. Please report back when you are ready."},{"cond":["quest 233 is 10"],"reply":"Excellent! Another job well done! Would you accept another mission?","fx":["quest 249 becomes 3"]},{"cond":["quest 231 is 1"],"reply":"You are not done with your current mission. Deliver that present to Fibula. Please report back when you are ready."},{"cond":["quest 231 is 2"],"reply":"Splendid, I knew we could trust you. I would like to ask for your help in another matter. Are you interested?"},{"cond":["quest 230 is 1"],"reply":"Do you bring ONE bone for our officers'' safety fund or ALL bones at once?"},{"cond":["quest 230 above 1","quest 230 below 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 1","quest 230 is 20"],"reply":"Do you bring a bone for our officers'' safety fund?"},{"cond":["quest 230 above 20"],"reply":"You have made it! We have enough bones for the fund! You remind me of myself when I was young! Interested in another mission?"},{"cond":["quest 229 above 0","quest 229 below 3"],"reply":"You are not done with your current mission. Find David Brassacres and hand him that bill. Report when you are ready."},{"cond":["quest 229 is 3"],"reply":"You truly got him? Quite impressive. You are a very prommising candidate! I think I have another mission for you. Are you interested?"},{"cond":["quest 228 is 1"],"reply":"You are not done with your current mission. The mailbox is still not fixed. Report if you are ready."},{"cond":["quest 228 is 2"],"reply":"Excellent, you got it fixed! This will teach this mailbox a lesson indeed! Are you interested in another assignment?"},{"cond":["quest 227 below 5"],"reply":"You are not done with your current mission. Make sure all the passages are secure. Report if you are ready."},{"cond":["quest 227 is 5"],"reply":"So you have finally made it! I did not think that you would have it in you ... However: are you ready for another assignment?"}]},{"say":"yes","reply":"Hm, I might consider your proposal, but first you will have to prove your worth by doing some tasks for us. Are you willing to do that?","alts":[{"other":true,"reply":"I thought so. The mail service is not for just anyone."}]}]'::jsonb, false, 'Return to Kevin for the last mission! Now Kevin gives you a letter to deliver to Markwin in Mintwallin. A Stealth Ring is advisable for this mission as he summons 4 Minotaur Archers, 2 Minotaur Guards, and 2 Minotaur Mages summoned at once!');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 60, 'go', 'In Thais, the Ancient Temple: follow the route down to Mintwallin, the minotaur city.', 32356, 32170, 7, null, null, '[]'::jsonb, null, '[]'::jsonb, false, 'When you are ready, go to Thais, Ancient Temple (Mapper Coords 126.100, 125.170, 7) and follow the route here to the Minotaur city of Mintwallin.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 70, 'talk', 'Say hi to Markwin (invisible or with a stealth ring; or from outside the castle to lure the guards a few at a time), then hi again and give him the letter.', null, null, null, 'Markwin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"No! The hornless have reached my city! BODYGUARDS TO ME!","fx":["quest 222 becomes 1","summons a minotaur guard","summons a minotaur guard","summons a minotaur mage","summons a minotaur mage","summons a minotaur archer","summons a minotaur archer","summons a minotaur archer","ends the conversation"],"cond":["quest 222 is 0"],"alts":[{"cond":["quest 245 is 2"],"reply":"Oh, it''s you again. What do you want, hornless messenger?"},{"reply":"Well ... you defeated my guards! Now everything is over! I guess I will have to answer your questions now."}]},{"say":"letter","reply":"A letter from my Moohmy?? Do you have a letter from my Moohmy to me?","cond":["quest 245 is 1"]},{"say":"yes","reply":"Uhm, well thank you, hornless beeing.","fx":["quest 245 becomes 2","takes letter to Markwin"],"cond":["if you have letter to Markwin"],"alts":[{"reply":"Don''t mock the king of the minotaurs or you will regret that!"},{"other":true,"reply":"Uh? What??"}]}]'::jsonb, false, 'As soon as you say "hi" to Markwin, he will call for his 8 bodyguards. You can also say ''hi'' to him from the outside of the castle. Say hi again, and give him his letter.');
  insert into public.map_quest_steps (quest_id, segment_id, sort, kind, text, x, y, z, npc, monster, items, object, dialog, checked, source) values (88, seg, 80, 'talk', 'Back to Kevin: ask about advancement. You are now an Arch Postman (royal mailboxes).', null, null, null, 'Kevin', null, '[]'::jsonb, null, '[{"say":"hi","reply":"Greetings <your name>, what brings you here?"},{"say":"advancement","reply":"You are worthy indeed. Do you want to advance in our guild?","cond":["quest 250 < quest 249"],"alts":[{"cond":["quest 250 >= quest 249"],"reply":"Sorry, but you are not yet ready for advancement."}]},{"say":"yes","reply":"I grant you the title of postman. You are now a full member of our guild. Here have your own officers hat and wear it with pride.","fx":["quest 250 becomes 2","you get post officers hat"],"cond":["quest 249 is 2"],"alts":[{"cond":["quest 249 is 3"],"reply":"From now on it shall be known that you are a grand postman. You are now a privileged member until the end of days. Most captains around the world have an agreement with our guild to transport our privileged members, like you, for less gold.","fx":["quest 250 becomes 3"]},{"cond":["quest 249 is 4"],"reply":"From now on you are a grand postman for special operations. You are an honoured member of our guild and earned the privilege of your own post horn. Here, take it.","fx":["quest 250 becomes 4","you get post horn"]},{"cond":["quest 249 is 5"],"reply":"I grant you the title of archpostman. You are a legend in our guild. As privilege of your newly aquired status you are allowed to make use of certain mailboxes in dangerous areas. Just look out for them and you''ll see.","fx":["quest 250 becomes 5"]}]}]'::jsonb, false, 'Return to Kevin and ask about advancement. You are now an Arch Postman! (You may now use royal mailboxes).');
